// PeerLive stub (resources/app.asar -> index.js). Generated by the PeerLive installer; replaces Vencord's
// one-line stub `require("<...>\\Vencord\\dist\\patcher.js")` and keeps the same contract:
//   PeerLive loader (hooks)  ->  official Vencord patcher.js  ->  Discord (_app.asar)
// Vencord's persistAfterDiscordUpdates copies THIS file into new app-* folders after Discord updates.
"use strict";
const PEERLIVE_LOADER = __PEERLIVE_LOADER__;
const VENCORD_PATCHER = __VENCORD_PATCHER__;
const fs = require("fs");

// Same thing Vencord's patcher.ts does before loading Discord, minus Vencord: used only when Vencord is gone.
function vanilla() {
    const path = require("path");
    const asarPath = path.join(path.dirname(require.main.filename), "..", "_app.asar");
    const pkg = require(path.join(asarPath, "package.json"));
    require.main.filename = path.join(asarPath, pkg.main);
    require("electron").app.setAppPath(asarPath);
    require(require.main.filename);
}

if (fs.existsSync(PEERLIVE_LOADER)) {
    require(PEERLIVE_LOADER).boot({ vencordPatcher: VENCORD_PATCHER, vanilla });
} else if (fs.existsSync(VENCORD_PATCHER)) {
    require(VENCORD_PATCHER);
} else {
    console.error("[PeerLive] Neither PeerLive nor Vencord found, starting Discord without mods");
    vanilla();
}
